"""Read-only audit of actual committed context-preference calls and exposure."""
import json,pathlib,math,hashlib,torch
R=pathlib.Path(__file__).resolve().parents[1];E=R/'execution';torch.set_num_threads(1)
cp=torch.load(R/'continue-10000/checkpoint.pt',map_location='cpu',weights_only=False);step=cp['step'];policy=json.loads((R/'policy.json').read_text());raw=(R/policy['contextPreference']['pool']).read_bytes();assert hashlib.sha256(raw).hexdigest()==policy['contextPreference']['poolSha256'];pool=json.loads(raw)['rows'];trace=[json.loads(l) for l in (R/'continue-10000/context-preference.jsonl').read_text().splitlines()];kept=[r for r in trace if r['step']<=step];assert [r['step'] for r in kept]==list(range(10,step+1,10));assert len(kept)==cp['contextPreferenceCalls'] and sum(r['pairs'] for r in kept)==cp['contextPreferencePairs'];assert cp['settings']['contextPreference']==policy['contextPreference'];seen=set()
for i,r in enumerate(kept):
 indices=[(i*2+j)%len(pool) for j in range(2)];examples=[pool[k] for k in indices];seen.update(indices);assert r['firstPoolIndex']==indices[0] and r['pairs']==2
 targets=sum(len(x['targetTokens']) for x in examples);inputs=sum(2*(len(x['prefixTokens'])+len(x['targetTokens'])) for x in examples)
 assert r['positiveTargetTokens']==targets and r['scoredTargetTokensBothContexts']==2*targets and r['inputTokensBothContexts']==inputs
 assert all(math.isfinite(r[k]) for k in ['loss','meanCorrectNll','meanMismatchedNll','meanContextGain']);assert abs(r['meanContextGain']-(r['meanMismatchedNll']-r['meanCorrectNll']))<2e-6
 a=r['meanCorrectNll']-r['meanMismatchedNll'];lower=max(a,0)+math.log1p(math.exp(-abs(a)));assert r['loss']+2e-6>=lower and r['loss']>=0
report=dict(actualRetainedOptimizerUpdates=step,actualAuxiliaryCalls=len(kept),actualPairs=sum(r['pairs'] for r in kept),positiveTargetTokens=sum(r['positiveTargetTokens'] for r in kept),scoredTargetTokensBothContexts=sum(r['scoredTargetTokensBothContexts'] for r in kept),inputTokensBothContexts=sum(r['inputTokensBothContexts'] for r in kept),uniquePoolPairsSeen=len(seen),frozenPoolPairs=len(pool),traceStepsAndCyclicIndicesExactlyVerified=True,exposureCountsExactlyVerified=True,allLoggedValuesFinite=True,lossJensenBoundPassed=True,mainPositiveTargetTokensSeparate=cp['seen_tokens'],mainExposureCountsExcludeAuxiliary=True,additionalOptimizerUpdates=0,scope='Auxiliary canonical original human TRAIN only; not free generation ability or new TEST',traceSha256=hashlib.sha256((R/'continue-10000/context-preference.jsonl').read_bytes()).hexdigest())
(E/'context-trace-audit.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
